CAT = "sirLaw"; SEG = "LAW"
Q = [
('Which British Columbia statute sets the rules for selling and serving liquor in licensed establishments?',
 'Liquor Control and Licensing Act', ['Liquor Licence and Control Act', 'Gaming, Liquor and Cannabis Act', 'Liquor Distribution and Sales Act'],
 "BC's Liquor Control and Licensing Act (2015) and its Regulation govern licensees. The Liquor Licence and Control Act is Ontario's law and the Gaming, Liquor and Cannabis Act is Alberta's."),
("Which of these is not liquor under BC's Act?",
 '0.5% alcohol-free beer', ['4% hard seltzer', '7% craft cider', '1.5% shandy'],
 'Section 1 of the Act defines liquor as a product containing more than 1% alcohol by volume, so a 0.5% beer is not liquor; all the others are.'),
("In British Columbia, a person is a minor for liquor purposes until what age?",
 "19", ["16", "18", "19", "21"],
 "The Act defines a minor by the Age of Majority Act, which sets the age of majority at 19. The Regulation also defines an adult as 19 or older.", "fixed"),
("Before a licensee may operate an establishment, the Act requires the licensee to:",
 "Complete the prescribed training", ["Hire a licensed security firm", "Post a food-safe permit", "Pass a police background interview"],
 "Section 60 says a licensee must not operate an establishment or event site without first completing a prescribed training program, which in BC is Serving It Right."),
('Who may sell, serve or supervise liquor service in a licensed establishment?',
 'Staff with the prescribed training', ['Any staff member who is 19 or older', 'Any staff the manager has approved', 'Staff with a bartending diploma'],
 'Regulation s. 143 says a licensee must not let anyone sell, serve or supervise liquor service without the prescribed training or recertification. Being 19 is not enough.'),
('Under the Regulation, a Serving It Right certificate stays valid for:',
 '5 years', ['2 years', '3 years', '4 years', '5 years'],
 'Section 184 of the Regulation says the certificate expires 5 years after the course is completed, and the expiry date is shown on it.',
 'fixed'),
("A certificate issued before mid-September 2015 with no expiry date printed on it:",
 "Has already expired", ["Never expires", "Lasts until the holder is 65", "Expires after 10 years of use"],
 "Regulation s. 184 says certificates with no expiry date that were valid when the section took effect expired on September 15, 2020."),
("What is the main purpose of the service area under a food primary licence?",
 "Serving food", ["Serving liquor", "Live entertainment", "Off-site catering"],
 "Regulation s. 16 says the primary purpose of a food primary business in the service area, while liquor is sold, must be the service of food."),
('A food primary licence requires the establishment to offer:',
 'Varied menu from an on-site kitchen', ['Snacks from a vending machine', 'One hot dish offered after 9 p.m.', 'Bar food during happy hour only'],
 'Regulation s. 18 requires a varied selection of food, including appetizers and main courses, prepared in a kitchen on the site.'),
("A liquor primary establishment must make which items available while liquor is served?",
 "Food and non-alcoholic drinks", ["Live music or entertainment", "A seat for every patron", "Taxi vouchers for every table"],
 "Regulation s. 10 requires food and non-alcoholic beverages at reasonable prices or free of charge, unless the general manager exempts the licensee."),
("Under the Regulation, the latest a bar or restaurant's hours of liquor service may run is:",
 "4 a.m.", ["1 a.m.", "2 a.m.", "3 a.m.", "4 a.m."],
 "For liquor primary and food primary licences, liquor service may start no earlier than 9 a.m. and must end no later than 4 a.m. the next day, within any limits the general manager sets.", "fixed"),
('The earliest a BC bar or restaurant may begin serving liquor is:',
 '9 a.m.', ['6 a.m.', '7 a.m.', '8 a.m.', '9 a.m.'],
 'Regulation ss. 10 and 18 set 9 a.m. as the earliest start for liquor service in liquor primary and food primary establishments. 7 a.m. is the earliest for retail stores.',
 'fixed'),
("After liquor service ends in a liquor primary, patrons must be cleared out within:",
 "30 minutes", ["10 minutes", "15 minutes", "30 minutes", "60 minutes"],
 "Regulation s. 89 requires patrons to be cleared from the service area within half an hour after the hours of liquor service end, unless the general manager authorizes otherwise.", "fixed"),
("How long after service ends may a patron in a BC restaurant keep drinking?",
 "Up to 30 minutes", ["Until the last glass is done", "Up to 15 minutes", "Up to 60 minutes"],
 "Regulation s. 91 bars drinking more than half an hour after the hours of liquor service end, so drinks must be finished within that half hour."),
('At closing in a food primary, which liquor may a diner keep and take home?',
 'Sealed, unfinished wine bottle', ['Half-finished pitcher of beer', 'Unfinished mixed drink in a cup', 'Opened cooler with a lid on'],
 'Regulation ss. 90 and 141 let a sealed, partly consumed bottle of wine leave the service area. Other open liquor is taken from patrons within half an hour.'),
('Which liquor may a patron drink in a BC service area?',
 'What that area sold or served', ['Any liquor bought that day', "Liquor from a friend's car", 'Wine a guest brought unopened'],
 'Regulation s. 141 says patrons may consume only liquor that was sold or served in that service area. Outside liquor brought in is not allowed unless the rules for that licence allow it.'),
('Under the Regulation, what may an employee not do while working?',
 'Have an alcoholic drink', ['Eat a staff meal', 'Pour a tasting sample', 'Refuse an intoxicated guest'],
 'Regulation s. 142 requires the licensee to make sure employees do not consume liquor while working, and employees must not do so.'),
("Topping up a premium vodka bottle with a cheaper brand is:",
 "Prohibited adulteration", ["Allowed if prices drop", "Allowed after closing", "A standard cost practice"],
 "Regulation s. 144 forbids diluting or adulterating liquor and refilling or topping up purchased bottles. Customers must get what the bottle says."),
("Which promotion breaks BC's rule against selling liquor in a way that encourages intoxication?",
 'Unlimited drinks for one price', ['Free soft drinks for drivers', 'Half-price appetizers all night', 'A non-alcoholic cocktail menu'],
 'Regulation s. 82 forbids providing unlimited or unspecified quantities of liquor for one price and any sales strategy likely to promote or encourage intoxication.'),
("A patron asks how much liquor is in each cocktail. The licensee must:",
 "Provide the quantities on request", ["Refuse, since recipes are private", "Give them only to staff", "Post them in the kitchen only"],
 "Regulation s. 83 requires licensees to give patrons, on request, a list of the quantities of liquor in drinks and their prices."),
("BC sets minimum prices for liquor drinks in licensed establishments mainly to:",
 "Discourage cheap heavy drinking", ["Protect brewery profits", "Raise sales tax revenue", "Keep menus the same province-wide"],
 "Regulation s. 84 sets a minimum price per ounce for each type of liquor, so drinks cannot be sold so cheaply that they encourage over-consumption. The amounts themselves change and are not asked."),
('Who can ask your staff and patrons to show identification during an inspection?',
 'Liquor inspectors', ['Liquor store clerks', 'Any licensee', 'Court sheriffs only'],
 "Section 42 of the Act lets the general manager, through inspectors, require a licensee's employees and patrons to produce identification during an inspection."),
('A licensee who hides records from a liquor inspector is breaking the rule against:',
 'Obstructing an inspection', ['Unlawful liquor advertising', 'A tied-house arrangement', 'Selling below minimum price'],
 'Section 43 says a licensee must not obstruct the general manager or withhold, destroy, conceal or refuse to provide information during an inspection.'),
('If a BC licensee breaks the liquor rules, the general manager may:',
 'Impose a penalty or suspension', ['Fine only the server personally', 'Close the business permanently', 'Only issue a written warning'],
 'Section 51 of the Act lets the general manager impose a monetary penalty or suspend the licence under a prescribed schedule. Courts can also convict for offences.'),
("When a corporation commits a liquor offence, a director who allowed it:",
 "Also commits an offence", ["Is never personally liable", "Is liable only if present", "Pays only the company's fine"],
 "Section 58 of the Act says an officer, director or agent who authorizes, permits or agrees to a corporation's offence also commits an offence."),
('Which number limit can never be exceeded in a liquor service area?',
 'Person capacity', ['Seats listed on the menu', 'Staff on the schedule', 'Tables per server'],
 'Regulation ss. 72 and 78 set a person capacity for each service area, and the number of people there must stay within it (and within the occupant load).'),
('A hotel guest may carry a drink from the lounge to their room only if they:',
 'Go directly and be sober', ['Pay a corkage fee first', 'Go before 11 p.m.', 'Use a lidded paper cup'],
 'Regulation s. 85 lets a registered guest take a drink to a guest room by a direct route, never when the patron appears intoxicated or has been violent or disorderly.'),
("A golfer may carry a drink to another service area on the course how?",
 "By a direct route only", ["Anywhere on the property", "Only in sealed cans", "Only before noon"],
 "Regulation s. 88 lets a golf course patron carry a drink by a direct route to another service area on the course. The direct-route rule applies, not a free roam."),
('Liquor advertising in British Columbia is:',
 'Allowed as the rules permit', ['Banned in every form', 'Unregulated if it is truthful', 'Allowed on radio only'],
 'Section 64 of the Act says a person must not advertise liquor except as the regulations allow. Advertising is not banned outright.'),
("A manufacturer pays a bar to pour only its beer and no competitor's. This is:",
 "A prohibited tied-house deal", ["Normal brand marketing", "Allowed with a sign posted", "Allowed for craft brewers only"],
 "Section 62 of the Act forbids arrangements to sell one manufacturer's liquor to the exclusion of others, and payments or gifts for promoting a brand."),
('Under the Act, the general manager may require licensees to give patrons and staff:',
 'Education material', ['Free transit passes', 'Drink tokens for drivers', 'Discount meal coupons'],
 'Section 63 lets the general manager require licensees and permittees to provide liquor-related education material to patrons and staff.'),
("A sealed bottle of liquor from a bar's off-sales may leave with a customer when:",
 'It is bought with a meal', ['The bar is about to close', 'The buyer is a regular', 'It is under a set price'],
 'Regulation ss. 9.1 and 16.1 let liquor primary and food primary licensees sell unopened liquor for removal only together with a meal for eating outside the establishment.'),
('How long must BC licensees keep sales and incident records?',
 'At least 6 years', ['At least 30 days', 'At least 1 year', 'At least 3 years', 'At least 6 years'],
 'Regulation s. 80 requires licensees to keep purchase, sales, disposal and incident records for at least 6 years, with some exceptions.',
 'fixed'),
('A newly hired bartender who has not yet passed the course may:',
 'Not serve until certified', ["Serve under a manager's eye", 'Serve for the first 30 days', 'Serve beer and wine only'],
 'Act s. 60 and Regulation s. 143 bar anyone from selling or serving liquor without the prescribed training. BC sets no grace period for new hires.'),
("A server certified in another province moves to BC. Under the program's rules:",
 'Current certificate accepted', ['Must retake within 7 days', 'Must work 30 days supervised', 'Must wait until age 21'],
 'Responsible Service BC says servers moving from another province with a valid, current certificate are exempt, though an employer may still require the BC course.'),
('Drinking liquor in a public park in BC is lawful only where:',
 'Designated by bylaw', ['The park has picnic tables', 'No children are nearby', 'The drink is in a cup'],
 'Section 73 of the Act bars drinking or open liquor outside listed places. Municipalities and regional districts may designate public places for drinking, and the bylaw must set the hours.'),
]
